# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#14532d" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">ABDULLAH BİN ÖMER\'İN (RA) HAYATI VE KATILDIĞI GAZVELER</text>\n\n  <rect x="15" y="54" width="215" height="190" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="215" height="26" fill="#15803d" rx="6"/>\n  <text x="122" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. AİLESİ VE DOĞUMU</text>\n  <text x="25" y="95" fill="#14532d" font-size="9.5" font-weight="bold">• Anne ve Babası:</text>\n  <text x="29" y="109" fill="#1e293b" font-size="9">Hz. Ömer (ra) ile Zeyneb binti</text>\n  <text x="29" y="122" fill="#1e293b" font-size="9">Maz\'ûn\'un (ra) oğludur.</text>\n  <text x="25" y="140" fill="#14532d" font-size="9.5" font-weight="bold">• Ablası:</text>\n  <text x="29" y="154" fill="#1e293b" font-size="9">Müminlerin Annesi Hz. Hafsa (ra)</text>\n  <text x="25" y="172" fill="#14532d" font-size="9.5" font-weight="bold">• Doğumu ve Hicreti:</text>\n  <text x="29" y="186" fill="#1e293b" font-size="9">Nübüvvetin 3. yılında Mekke\'de doğdu;</text>\n  <text x="29" y="199" fill="#1e293b" font-size="9">küçük yaşta Müslüman olup hicret etti.</text>\n  <text x="25" y="217" fill="#14532d" font-size="9.5" font-weight="bold">• Vefatı:</text>\n  <text x="29" y="231" fill="#1e293b" font-size="9">Miladi 692\'de Mekke\'de (85 yaşında).</text>\n\n  <rect x="242" y="54" width="215" height="190" fill="#eff6ff" stroke="#2563eb" stroke-width="1.5" rx="8"/>\n  <rect x="242" y="54" width="215" height="26" fill="#1d4ed8" rx="6"/>\n  <text x="350" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. GAZVELER VE FETİHLER</text>\n  <text x="252" y="95" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Bedir ve Uhud:</text>\n  <text x="256" y="109" fill="#1e293b" font-size="9">Yaşı küçük olduğu için izin verilmedi.</text>\n  <text x="252" y="127" fill="#1e3a8a" font-size="9.5" font-weight="bold">• İlk Gazvesi (15 Yaşında):</text>\n  <text x="256" y="141" fill="#1d4ed8" font-size="9.5" font-weight="bold">Hendek Savaşı (627)</text>\n  <text x="252" y="159" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Sonraki Gazve ve Fetihler:</text>\n  <text x="256" y="173" fill="#1e293b" font-size="9">Hayber, Mekke\'nin Fethi, Huneyn;</text>\n  <text x="256" y="186" fill="#1e293b" font-size="9">Suriye-Irak fetihleri, Yermük, Nihavend,</text>\n  <text x="256" y="199" fill="#1e293b" font-size="9">Mısır\'ın Fethi ve Ebu Eyyüb el-Ensari</text>\n  <text x="256" y="212" fill="#1e293b" font-size="9">ile birlikte İstanbul kuşatması.</text>\n\n  <rect x="470" y="54" width="215" height="190" fill="#fefce8" stroke="#ca8a04" stroke-width="1.5" rx="8"/>\n  <rect x="470" y="54" width="215" height="26" fill="#b45309" rx="6"/>\n  <text x="577" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">3. BİRLİK BİLİNCİ VE TAKVASI</text>\n  <text x="480" y="95" fill="#78350f" font-size="9.5" font-weight="bold">• Fitneden Uzak Durması:</text>\n  <text x="484" y="109" fill="#1e293b" font-size="9">Müslümanlar arasındaki iç savaş ve</text>\n  <text x="484" y="122" fill="#1e293b" font-size="9">fitne olaylarında hiçbir çatışmaya</text>\n  <text x="484" y="135" fill="#1e293b" font-size="9">girmedi, daima barışı savundu.</text>\n  <text x="480" y="156" fill="#78350f" font-size="9.5" font-weight="bold">• Nebevî Övgü ve Gece Namazı:</text>\n  <text x="484" y="170" fill="#92400e" font-size="8.8" font-style="italic">"Abdullah ne iyi bir adamdır, keşke</text>\n  <text x="484" y="183" fill="#92400e" font-size="8.8" font-style="italic">geceleyin namaz kılıyor olsaydı!"</text>\n  <text x="484" y="199" fill="#1e293b" font-size="9">Bu müjdeden sonra teheccüd namazını</text>\n  <text x="484" y="212" fill="#1e293b" font-size="9">hayatı boyunca hiç terk etmedi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e3a8a" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">ABDULLAH BİN ÖMER\'İN (RA) İLMÎ YÖNÜ VE SÜNNETE BAĞLILIĞI</text>\n\n  <rect x="15" y="54" width="325" height="122" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <text x="177" y="73" fill="#1e3a8a" font-size="11" font-weight="bold" text-anchor="middle">HADİS İLMİNDEKİ YERİ (MÜKSİRÛN)</text>\n  <line x1="25" y1="79" x2="330" y2="79" stroke="#3b82f6" stroke-width="1"/>\n  <text x="25" y="96" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold">2630 Hadis Rivayeti:</tspan> Ebu Hureyre\'den (ra) sonra</text>\n  <text x="25" y="110" fill="#1e293b" font-size="9.5">  en çok hadis rivayet eden <tspan font-weight="bold" fill="#1d4ed8">ikinci sahabidir</tspan>.</text>\n  <text x="25" y="127" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold">Lafzen Rivayet Titizliği:</tspan> Hadis metinlerindeki</text>\n  <text x="25" y="141" fill="#1e293b" font-size="9.5">  kelimeleri eş anlamlılarıyla bile değiştirmeden</text>\n  <text x="25" y="155" fill="#1e293b" font-size="9.5">  Hz. Peygamber\'den duyduğu gibi aktarmıştır.</text>\n\n  <rect x="360" y="54" width="325" height="122" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5" rx="8"/>\n  <text x="522" y="73" fill="#14532d" font-size="11" font-weight="bold" text-anchor="middle">FIKIH İLMİNDEKİ YERİ (FUKAHA-İ SEB\'A)</text>\n  <line x1="370" y1="79" x2="675" y2="79" stroke="#22c55e" stroke-width="1"/>\n  <text x="370" y="96" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold">Yedi Fakih Sahabi:</tspan> Medine\'de en çok fetva veren</text>\n  <text x="370" y="110" fill="#1e293b" font-size="9.5">  yedi âlim sahabiden (<tspan font-weight="bold" fill="#15803d">Fukaha-i Seb\'a</tspan>) biridir.</text>\n  <text x="370" y="127" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold">Fetva Usulü (4 Aşamalı Sıralama):</tspan></text>\n  <text x="370" y="141" fill="#1e293b" font-size="9.5">  1. Kur\'an-ı Kerim  -&gt;  2. Hz. Peygamber\'in Sünneti</text>\n  <text x="370" y="155" fill="#1e293b" font-size="9.5">  -&gt;  3. Sahabe İcmaı  -&gt;  4. Kıyas (İçtihat)</text>\n\n  <rect x="15" y="186" width="670" height="60" fill="#fffbeb" stroke="#f59e0b" stroke-width="1.5" rx="8"/>\n  <text x="350" y="206" fill="#92400e" font-size="10.5" font-weight="bold" text-anchor="middle">HZ. PEYGAMBER\'İN SÜNNETİNE VE HATIRASINA DERİN SEVGİSİ</text>\n  <text x="350" y="224" fill="#1e293b" font-size="9.5" text-anchor="middle">Hz. Peygamber\'in namaz kıldığı mescitlerde namaz kılmış, yürüdüğü yollarda yürümüş ve</text>\n  <text x="350" y="238" fill="#1e293b" font-size="9.5" text-anchor="middle">Resulullah\'ın altında gölgelendiği ağacı kurumasın diye bizzat sulayarak sünnete bağlılığın zirve örneği olmuştur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#4c1d95" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">HADİSTEN HAYATA: KUR\'AN VE SÜNNETE SARILMAK &amp; ZEYD BİN HARİSE (RA)</text>\n\n  <rect x="15" y="54" width="330" height="190" fill="#f5f3ff" stroke="#8b5cf6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="330" height="26" fill="#6d28d9" rx="6"/>\n  <text x="180" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">İKİ EMANET VE BİDATTEN SAKINMA</text>\n  <text x="25" y="94" fill="#4c1d95" font-size="9.5" font-weight="bold">• İlim ve Bilinç (Zümer, 9):</text>\n  <text x="29" y="108" fill="#1e293b" font-size="9">"Hiç bilenlerle bilmeyenler bir olur mu?"</text>\n  <text x="25" y="126" fill="#4c1d95" font-size="9.5" font-weight="bold">• Veda Hutbesi\'ndeki İki Emanet:</text>\n  <text x="29" y="140" fill="#1e293b" font-size="9">1) Allah\'ın Kitabı (Kur\'an-ı Kerim)</text>\n  <text x="29" y="153" fill="#1e293b" font-size="9">2) Peygamber\'in Sünneti</text>\n  <text x="25" y="171" fill="#4c1d95" font-size="9.5" font-weight="bold">• Hadis-i Şerif (Buhari, İ\'tisam, 2):</text>\n  <text x="29" y="185" fill="#5b21b6" font-size="8.8" font-style="italic">"Sözün en doğrusu Allah\'ın kitabıdır, hidayetin</text>\n  <text x="29" y="198" fill="#5b21b6" font-size="8.8" font-style="italic">en güzeli Muhammed\'in hidayetidir, işlerin en</text>\n  <text x="29" y="211" fill="#5b21b6" font-size="8.8" font-style="italic">kötüsü sonradan ortaya çıkanlardır; her bidat</text>\n  <text x="29" y="224" fill="#5b21b6" font-size="8.8" font-style="italic">dalalettir (sapıklıktır)."</text>\n  <text x="29" y="238" fill="#1e293b" font-size="8.5">İslam cehaleti, kör taklidi, bidat ve hurafeyi reddeder.</text>\n\n  <rect x="355" y="54" width="330" height="190" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5" rx="8"/>\n  <rect x="355" y="54" width="330" height="26" fill="#db2777" rx="6"/>\n  <text x="520" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">PEYGAMBER SEVGİSİ: ZEYD BİN HARİSE (RA)</text>\n  <text x="365" y="95" fill="#831843" font-size="9.5" font-weight="bold">• Olayın Gelişimi:</text>\n  <text x="369" y="109" fill="#1e293b" font-size="9">Küçük yaşta kaçırılıp Mekke\'de satılan Zeyd,</text>\n  <text x="369" y="122" fill="#1e293b" font-size="9">Hz. Hatice tarafından Hz. Peygamber\'e hediye</text>\n  <text x="369" y="135" fill="#1e293b" font-size="9">edildi ve Efendimiz onu hemen azat etti.</text>\n  <text x="365" y="153" fill="#831843" font-size="9.5" font-weight="bold">• Tarihi Tercih Anı:</text>\n  <text x="369" y="167" fill="#1e293b" font-size="9">Babası Harise ve amcası Kâb fidye ile onu</text>\n  <text x="369" y="180" fill="#1e293b" font-size="9">almaya geldiğinde Hz. Peygamber seçimi Zeyd\'e</text>\n  <text x="369" y="193" fill="#1e293b" font-size="9">bıraktı. Zeyd bin Harise, Hz. Peygamber\'in</text>\n  <text x="369" y="206" fill="#9d174d" font-size="9" font-weight="bold">eşsiz şefkat ve adaletini anne-babasına</text>\n  <text x="369" y="219" fill="#9d174d" font-size="9" font-weight="bold">tercih ederek onun yanında kalmayı seçti.</text>\n  <text x="369" y="235" fill="#1e293b" font-size="8.5">Bunun üzerine babası ve amcası da memnuniyetle döndü.</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
